<?php declare(strict_types=1); namespace App\Repositories; use PDO; final class LiquidityRoundRepository{private $pdo; public function __construct(?PDO $pdo=null){$this->pdo=$pdo??\App\Core\Database::connection();} public function createRound($sid,$r){$this->pdo->prepare('INSERT IGNORE INTO liquidity_rounds (session_id,round_number,status,started_at) VALUES (?,?,\'open\',NOW())')->execute([$sid,$r]);} public function getCurrentRound($sid,$r){$s=$this->pdo->prepare('SELECT * FROM liquidity_rounds WHERE session_id=? AND round_number=?');$s->execute([$sid,$r]);return $s->fetch()?:null;} public function getCurrentRoundForUpdate($sid,$r){$s=$this->pdo->prepare('SELECT * FROM liquidity_rounds WHERE session_id=? AND round_number=? FOR UPDATE');$s->execute([$sid,$r]);return $s->fetch()?:null;} public function closeRound($sid,$r):bool{$s=$this->pdo->prepare("UPDATE liquidity_rounds SET status='closed', ended_at=NOW(), closed_at=NOW(), updated_at=NOW() WHERE session_id=? AND round_number=? AND status='open'");$s->execute([$sid,$r]);return $s->rowCount()>0;} public function markEconomyApplied($sid,$r):void{$this->pdo->prepare("UPDATE liquidity_rounds SET maintenance_fee_applied=1, dividends_applied=1, updated_at=NOW() WHERE session_id=? AND round_number=?")->execute([$sid,$r]);} public function hasOpenRound($sid,$r){$s=$this->pdo->prepare("SELECT COUNT(*) FROM liquidity_rounds WHERE session_id=? AND round_number=? AND status='open'");$s->execute([$sid,$r]);return (int)$s->fetchColumn()>0;}}
